<?php
$client=authClient();
if (!$client) { header('Location: '.url('entrar?return=minha-conta'),true,302);exit; }
$code=(string)($_GET['codigo']??'');
$booking=sql('SELECT a.*,s.name service_name,st.name staff_name FROM appointments a JOIN services s ON s.id=a.service_id JOIN staff st ON st.id=a.staff_id WHERE a.confirmation_code=? AND a.client_id=?',[$code,$client['id']])->fetch();
if(!$booking){http_response_code(404);pageStart('Agendamento não encontrado');echo '<section class="section container"><h1>Não encontramos este agendamento.</h1><a class="btn btn-primary" href="'.e(url('minha-conta')).'">Minha conta</a></section>';pageEnd();return;}
$share='Meu agendamento na '.salon()['salon_name'].': '.$booking['service_name'].' com '.$booking['staff_name'].' em '.date('d/m/Y',strtotime($booking['scheduled_date'])).' às '.substr($booking['starts'],0,5).'. Código: '.$booking['confirmation_code'];
pageStart('Agendamento confirmado'); ?>
<section class="section confirmation-section"><div class="container"><div class="confirmation-card"><span class="success-emblem"><i data-lucide="check"></i></span><span class="eyebrow">TUDO PRONTO</span><h1>Seu momento está <em>reservado!</em></h1><p>Recebemos o seu agendamento com carinho. Guarde as informações abaixo.</p><div class="booking-ticket"><div class="ticket-number">Nº do agendamento <strong><?=e($booking['confirmation_code'])?></strong></div><div class="ticket-grid"><div><span>Serviço</span><strong><?=e($booking['service_name'])?></strong></div><div><span>Profissional</span><strong><?=e($booking['staff_name'])?></strong></div><div><span>Data</span><strong><?=date('d/m/Y',strtotime($booking['scheduled_date']))?></strong></div><div><span>Horário</span><strong><?=e(substr($booking['starts'],0,5))?></strong></div><div><span>Duração</span><strong><?=e($booking['duration_minutes'])?> min</strong></div><div><span>Valor</span><strong><?=money($booking['price_snapshot'])?></strong></div></div></div><div class="confirmation-actions"><a class="btn btn-primary" href="<?=e(url('minha-conta'))?>"><i data-lucide="calendar-check"></i> Meus agendamentos</a><a class="btn btn-outline" target="_blank" rel="noopener noreferrer" href="<?=e('https://wa.me/?text='.rawurlencode($share))?>"><i data-lucide="message-circle"></i> Compartilhar pelo WhatsApp</a></div><small>O compartilhamento abre o WhatsApp com uma mensagem pronta. Nenhuma mensagem foi enviada automaticamente.</small></div></div></section>
<?php pageEnd(); ?>
